"""## **Data Pre-processing**

converted the date columns into proper datetime format in pandas
"""

# convert the those date columns into date
date_cols = ["Received_Date", "Last_Purchase_Date", "Expiry_Date", "Audit_Date"]
for col in date_cols:
    df[col] = pd.to_datetime(df[col], dayfirst=True, errors="coerce")

"""## changed the datatype object into int and float for required columns"""

num_cols = [
    'Stock_Age_Days',
    'Quantity_On_Hand',
    'Quantity_Reserved',
    'Quantity_Committed',
    'Damaged_Qty',
    'Returns_Qty',
    'Reorder_Point',
    'Safety_Stock',
    'Lead_Time_Days',

]

df[num_cols] = df[num_cols].apply(pd.to_numeric, errors='coerce').fillna(0).astype(int)

# convert the Forecast_Next_30d datatype as int and corrected the format
df["Forecast_Next_30d"] = (
    df["Forecast_Next_30d"]
    .astype(str)
    .str.replace(".", "", regex=False)
    .str.replace(",", "", regex=False)
    .astype(int)
)

# convert the Days_of_Inventory datatype as int and corrected the format
df["Days_of_Inventory"] = (
    df["Days_of_Inventory"]
    .astype(str)
    .str.replace(",", ".", regex=False)
    .astype(float)
)

""" convert those columns datatype as float and corrected the format and also proper currency format
 columns are

    'Total_Inventory_Value_USD',
    'Last_Purchase_Price_USD',
    'Unit_Cost_USD'
"""

float_cols = [
    'Total_Inventory_Value_USD',
    'Last_Purchase_Price_USD',
    'Unit_Cost_USD'
]

for col in float_cols:

    df[col] = (
        df[col]
        .astype(str)
        .str.replace("$", "", regex=False)   # remove $
        .str.replace(".", "", regex=False)   # remove thousand separator
        .str.replace(",", ".", regex=False)  # fix decimal
        .astype(float)
    )
    df[col] = df[col].map("${:,.2f}".format)

df['Total_Inventory_Value_USD']

# changed the SKU_Churn_Rate datatype into float
df["SKU_Churn_Rate"] = (
    df["SKU_Churn_Rate"]
    .astype(str)
    .str.replace(".", "", regex=False)
    .str.replace(",", ".", regex=False)
    .astype(float)
)

df["SKU_Churn_Rate"]

"""### Rate_Level is a derived categorical column used to classify values into different levels (e.g., Low, Medium, High) based on predefined thresholds. This helps simplify analysis and makes it easier to identify patterns, risks, or performance segments in the data."""

df["Rate_Level"] = pd.cut(df["SKU_Churn_Rate"],
                         bins=[0, 3, 10, 25],
                         labels=["Low", "Medium", "High"])

df["Rate_Level"]

df.groupby("Rate_Level", observed=True)["Rate_Level"].count()

