# changed the Order_Frequency_per_month datatype into float
df['Order_Frequency_per_month'] = df['Order_Frequency_per_month'].astype(str).str.replace(',', '.', regex=False).astype(float)

# changed the Supplier_OnTime_Pct datatype into float

