"""## **REORDER AND RISK ANALYSIS**

### Reorder analysis is used to determine the optimal point to replenish inventory to avoid stockouts and overstocking. Risk analysis helps identify potential supply chain issues such as delays, shortages, and excess inventory. Together, they enable proactive inventory management, improve efficiency, and reduce operational risks.

Reorder Point is used to determine the exact stock level at which a new order should be placed. It helps prevent stockouts by considering lead time and average demand, ensuring continuous product availability while optimizing inventory levels.
"""

# Reorder_Point
df["Reorder_Point"] = df["Avg_Daily_Sales"] * df["Lead_Time_Days"]

"""Stockout Risk Indicator was created by comparing Days of Inventory with Supplier Lead Time to identify items likely to run out before replenishment. This helps proactively flag high-risk SKUs (True = stockout risk) and ensures timely procurement to avoid service disruptions"""

# Stockout Risk Indicator
df["Stockout_Risk"] = df["Days_of_Inventory"] < df["Lead_Time_Days"]

# Inventory Coverage Gap
df["Coverage_Gap"] = (
    df["Lead_Time_Days"] - df["Days_of_Inventory"]
).clip(lower=0)

df["Risk_Level"] = df["Coverage_Gap"].apply(
    lambda x: "High" if x >= 5
    else "Medium" if x >= 2
    else "Low"
)

import seaborn as sns
import matplotlib.pyplot as plt

risk_summary = df.groupby(["Warehouse_ID", "Risk_Level"]).size().unstack(fill_value=0)

risk_summary.plot(
    kind="bar",
    stacked=True,
    figsize=(9,5)
)

plt.title("Warehouse-wise Risk Distribution")
plt.xlabel("Warehouse ID")
plt.ylabel("Number of SKUs")
plt.xticks(rotation=45)

plt.show()

reorder_summary = df.groupby("Warehouse_ID")["Reorder_Flag"].sum()

plt.figure(figsize=(8,5))
sns.barplot(x=reorder_summary.index, y=reorder_summary.values)

plt.title("Reorder Required Items per Warehouse")
plt.xlabel("Warehouse ID")
plt.ylabel("Count of Reorder Items")

plt.show()

"""## **OPTIMIZATION ANALYSIS**

### Optimization analysis helps identify inefficient inventory patterns and provides actionable strategies to improve stock levels, reduce costs, and prevent stockouts. By combining risk, reorder signals, and inventory coverage, we prioritize items and warehouses that need immediate attention.
"""

# Optimization score
df["Optimization_Score"] = (
    df["Coverage_Gap"] * 2 +
    df["Stockout_Risk"].astype(int) * 5 +
    df["Reorder_Flag"].astype(int) * 3
)

import seaborn as sns
